INSERT INTO feature VALUES('change-coalescing','editor','A burst of changes judged once','language-server','implemented','ordinary',NULL,'Every `didChange` already in the inbox for a document is applied in order before the judgement, which runs once at the last version; a request a drained change overtakes is answered `ContentModified`, and a judgement a newer change overtakes is retired at its next poll, before each declaration it checks.','surface-lsp surface-session','crates/surface-lsp/src/server.rs crates/surface-session/tests/session.rs',NULL,'#1547');
